script.text:
			&OutlineEntry;
			/* <flatten type="Javascript"> */
function active$VoucherFilter$(sender) {sender.add_onResponseComplete(on$Filter$ResponseComplete);
	changeLookupReadonly(sender, 'ma_dvcs');
	changeLookupReadonly(sender, 'nh_kh1');
	changeLookupReadonly(sender, 'nh_kh2');
	changeLookupReadonly(sender, 'nh_kh3');
}
function close$VoucherFilter$(sender) {try {sender.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid, k = new Array()
				, dv = $func.trim(f.getItemValue('ma_dvcs'))
				, _nh_kh1 = $func.trim(f.getItemValue('nh_kh1'))
				, _nh_kh2 = $func.trim(f.getItemValue('nh_kh2'))
				, _nh_kh3 = $func.trim(f.getItemValue('nh_kh3'))
				, xloai_kh = $func.trim(f.getItemValue('xloai_kh'));

			if (xloai_kh == '1') Array.add(k, {Name: 'kh_yn', Opr: '=', Value: 1, Type: 'String', Ignore: false});
			if (xloai_kh == '2') Array.add(k, {Name: 'cc_yn', Opr: '=', Value: 1, Type: 'String', Ignore: false});
			if (xloai_kh == '3') Array.add(k, {Name: 'nv_yn', Opr: '=', Value: 1, Type: 'String', Ignore: false});
			if (_nh_kh1) Array.add(k, {Name: 'dbo.ff_ExactInlist(nh_kh1, \'' + _nh_kh1 + '\')', Opr: '=', Value: 1, Type: 'String', Ignore: false});
			if (_nh_kh2) Array.add(k, {Name: 'dbo.ff_ExactInlist(nh_kh2, \'' + _nh_kh2 + '\')', Opr: '=', Value: 1, Type: 'String', Ignore: false});
			if (_nh_kh3) Array.add(k, {Name: 'dbo.ff_ExactInlist(nh_kh3, \'' + _nh_kh3 + '\')', Opr: '=', Value: 1, Type: 'String', Ignore: false});
			if (dv) Array.add(k, {Name: 'dbo.zcff_ExactInlist(list_dvcs, \'' + dv + '\')', Opr: '=', Value: 1, Type: 'String', Ignore: false});

			g.set_externalKey(k);
			break;
		default:
				break;
	}
}
/* </flatten> */
